import { pgTable, serial, text, timestamp } from "drizzle-orm/pg-core";

export const users = pgTable("users", {
  id: serial("id").primaryKey(),
  email: text("email").notNull().unique(),
  name: text("name").notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export type UserRow = typeof users.$inferSelect;
export type NewUserRow = typeof users.$inferInsert;
EOF
cat > src/db/index.ts <<'EOF'
import { drizzle } from "drizzle-orm/postgres-js";
import postgres from "postgres";
import * as schema from "./schema";

const globalForDb = globalThis as unknown as { pgClient?: postgres.Sql };

function client(): postgres.Sql {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error("DATABASE_URL is not set (see .env.example)");
  // Reuse the connection across dev hot reloads.
  return (globalForDb.pgClient ??= postgres(url));
}

let instance: ReturnType<typeof create> | undefined;
function create() {
  return drizzle(client(), { schema });
}

// Lazy so importing this module (e.g. during `next build`) doesn't need a database.
export function db() {
  return (instance ??= create());
}
EOF
cat > drizzle.config.ts <<'EOF'
import { defineConfig } from "drizzle-kit";

export default defineConfig({
  dialect: "postgresql",
  schema: "./src/db/schema.ts",
  out: "./drizzle",
  dbCredentials: { url: process.env.DATABASE_URL! },
});
EOF
cat > scripts/migrate.ts <<'EOF'
import { drizzle } from "drizzle-orm/postgres-js";
import { migrate } from "drizzle-orm/postgres-js/migrator";
import postgres from "postgres";

const url = process.env.DATABASE_URL;
if (!url) throw new Error("DATABASE_URL is not set");
const sql = postgres(url, { max: 1 });
await migrate(drizzle(sql), { migrationsFolder: "./drizzle" });
await sql.end();
console.log("migrations applied");
EOF
cat > scripts/seed.ts <<'EOF'
import { drizzle } from "drizzle-orm/postgres-js";
import postgres from "postgres";
import { users } from "../src/db/schema";

const url = process.env.DATABASE_URL;
if (!url) throw new Error("DATABASE_URL is not set");
const sql = postgres(url, { max: 1 });
await drizzle(sql)
  .insert(users)
  .values([
    { email: "ada@example.com", name: "Ada", createdAt: new Date("2026-01-04") },
    { email: "grace@example.com", name: "Grace", createdAt: new Date("2026-02-11") },
  ])
  .onConflictDoNothing();
await sql.end();
console.log("seeded");
EOF
cat > src/lib/users.ts <<'EOF'
import { asc, eq } from "drizzle-orm";
import { db } from "@/db";
import { users, type UserRow } from "@/db/schema";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

function toUser(row: UserRow): User {
  return {
    id: String(row.id),
    email: row.email,
    name: row.name,
    createdAt: row.createdAt.toISOString().slice(0, 10),
  };
}

export async function listUsers(): Promise<User[]> {
  const rows = await db().select().from(users).orderBy(asc(users.id));
  return rows.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  if (!/^\d+$/.test(id)) return undefined;
  const [row] = await db().select().from(users).where(eq(users.id, Number(id))).limit(1);
  return row && toUser(row);
}

// TODO: there is no real session handling yet — the dashboard just picks the first user.
export async function getCurrentUser(): Promise<User | undefined> {
  const [row] = await db().select().from(users).orderBy(asc(users.id)).limit(1);
  return row && toUser(row);
}
EOF
